 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))
    if not centers:
        return out

    row_counts = [sum(v == 2 for v in row) for row in grid]
    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    horizontal_rails = max(row_counts) > max(col_counts)
    if horizontal_rails:
        rail_coords = [r for r, n in enumerate(row_counts) if n >= w - 2]
    else:
        rail_coords = [c for c, n in enumerate(col_counts) if n >= h - 2]

    for r, c in centers:
        if horizontal_rails:
            # Project perpendicular to horizontal rails.
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            intersections = [(rr, c) for rr in rail_coords if rr != r]
        else:
            # Project perpendicular to vertical rails.
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            intersections = [(r, cc) for cc in rail_coords if cc != c]

        # At each crossed rail, reproduce the 3x3 ring as a 1 outline,
        # retaining the 2 at its center and any original 3 cells.
        for rr, cc in intersections:
            for ar in range(max(0, rr - 1), min(h, rr + 2)):
                for ac in range(max(0, cc - 1), min(w, cc + 2)):
                    if (ar, ac) != (rr, cc) and grid[ar][ac] != 3:
                        out[ar][ac] = 1
    return out
